  // ---- seed guard ----
  seed_title: { en: "Stop: this page wants your recovery phrase", tr: "Dur: bu sayfa kurtarma ifadenizi istiyor", de: "Stopp: Diese Seite will Ihre Wiederherstellungsphrase", es: "Alto: esta página quiere tu frase de recuperación", fr: "Stop : cette page veut votre phrase de récupération", pt_BR: "Pare: esta página quer sua frase de recuperação", ru: "Стоп: эта страница запрашивает вашу seed-фразу", hi: "रुकें: यह पेज आपका रिकवरी फ्रेज़ माँग रहा है", zh_CN: "停止：此页面想要您的助记词", ja: "停止：このページはリカバリーフレーズを要求しています", ko: "중지: 이 페이지가 복구 구문을 요구합니다", vi: "Dừng lại: trang này muốn cụm từ khôi phục của bạn", id: "Berhenti: halaman ini meminta frasa pemulihan Anda" },
