const LANGS = ["en", "tr", "de", "es", "fr", "pt_BR", "ru", "hi", "zh_CN", "ja", "ko", "vi", "id"];
let missing = 0;
for (const lang of LANGS) {
  const out = {};
  for (const [key, byLang] of Object.entries(S)) {
    const msg = byLang[lang] ?? byLang.en;
    if (byLang[lang] === undefined) missing++;
    out[key] = { message: msg };
  }
  mkdirSync(`public/_locales/${lang}`, { recursive: true });
  writeFileSync(`public/_locales/${lang}/messages.json`, JSON.stringify(out, null, 2) + "\n");
}
console.log(`locales: ${LANGS.length} languages, ${Object.keys(S).length} keys${missing ? `, ${missing} fell back to en` : ""}`);
